  const aiTag = `<span style="height:22px;padding:0 8px;border-radius:999px;background:var(--accent-tint);color:var(--accent-fg);font-size:11px;font-weight:700;display:inline-flex;align-items:center;gap:4px;flex-shrink:0">${I('AudioLines', 11, 'currentColor', 2.4)}Bio</span>`;
