  const prod = (src, t, p) => `<div style="display:flex;flex-direction:column;gap:8px"><div style="height:150px;border-radius:18px;background:${img(src)}"></div><div style="font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${t}</div>${Amt(p, { size: 14.5, dec: false })}</div>`;
