  const tickBig = (k) => `<span style="width:44px;height:44px;border-radius:14px;background:var(--surface-sunken);display:grid;place-items:center;flex-shrink:0">${tick(k, 26)}</span>`;
  const offer = (k, st, until = '12 Oct 2026') => card(rowx(tickBig(k === 'creator' ? 'creator' : 'pro') + `<div style="flex:1"><div style="font-size:15.5px;font-weight:600">${k === 'creator' ? 'Creator tick' : 'Professional tick'}</div><div style="font-size:12.5px;color:var(--text-muted);margin-top:3px">${st === 'active' ? 'Active until ' + until : '₦2,000 a year'}</div></div>` + (st === 'active' ? pill('Active', 'positive', 'Check') : Btn('Get it', { size: 'sm', full: false })), 12), { pad: '14px' });
  const BEN = [['Upload', 'Up to 25 uploads', 'Free accounts get 5'], ['HardDrive', '10 GB library space', 'Free accounts get 1 GB'], ['TrendingUp', 'Reach more people', 'Your content is pushed further'], ['BadgeCheck', 'Tick beside your name', 'And you can host events']];
  const benRows = (sm) => BEN.map(([ic, t, s], i) => `<div style="display:flex;align-items:center;gap:12px;padding:${sm ? 8 : 10}px 0;${i ? 'box-shadow:inset 0 1px 0 var(--border-hairline)' : ''}"><span style="width:34px;height:34px;border-radius:10px;background:var(--accent-tint);display:grid;place-items:center;flex-shrink:0">${I(ic, 17, 'var(--accent-fg)', 2)}</span><div style="flex:1"><div style="font-size:14.5px;font-weight:600">${t}</div><div style="font-size:12.5px;color:var(--text-muted);margin-top:1px">${s}</div></div></div>`).join('');
  const perks = card(col(label('Every tick gives you') + `<div>${benRows()}</div>`, 6), { pad: '12px 16px' });
  const verifBody = (kyc, pro = 'buy', creator = 'active', extra = '', proUntil) => nav('Verification') + body(kycPanel(kyc) + col(label('Your ticks') + extra + offer('creator', creator) + offer('professional', pro, proUntil) + perks, 10), { gap: 20, pb: 40 });
  const verif = phone(verifBody('pending'));
