  const pinV = phone(verifBody('pending') + sheet(col(`<div style="text-align:center;display:flex;flex-direction:column;gap:6px">${h1('Enter your PIN', { size: 21 })}${muted('₦2,000 for the professional tick')}</div>`, 6) + `<div style="padding:8px 0">${dots(2)}</div>` + keypad({ left: 'face' }), { gap: 14 }));
